            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Catalyst Center assurance issues whose latest status in the selected window is active, with event-time issue observations retained as trend context\\."
            }
        },
